import { User } from '../types';

const USER_KEY = 'nsf_user';
const SESSION_KEY = 'nsf_session';

export const signUp = (name: string, email: string, password: string): Promise<User> => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const existing = localStorage.getItem(USER_KEY);
      if (existing) {
        const users: User[] = JSON.parse(existing);
        if (users.find(u => u.email === email)) {
          reject(new Error('User already exists'));
          return;
        }
      }

      const newUser: User = {
        name,
        email,
        passwordHash: btoa(password), // Mock encryption
        confirmed: false
      };

      const users = existing ? JSON.parse(existing) : [];
      users.push(newUser);
      localStorage.setItem(USER_KEY, JSON.stringify(users));
      resolve(newUser);
    }, 800);
  });
};

export const logIn = (email: string, password: string): Promise<User> => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const existing = localStorage.getItem(USER_KEY);
      if (!existing) {
        reject(new Error('User not found'));
        return;
      }
      const users: User[] = JSON.parse(existing);
      const user = users.find(u => u.email === email && u.passwordHash === btoa(password));

      if (!user) {
        reject(new Error('Invalid credentials'));
        return;
      }

      localStorage.setItem(SESSION_KEY, JSON.stringify(user));
      resolve(user);
    }, 800);
  });
};

export const logOut = (): void => {
  localStorage.removeItem(SESSION_KEY);
};

export const getSession = (): User | null => {
  const session = localStorage.getItem(SESSION_KEY);
  return session ? JSON.parse(session) : null;
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { College, ComparisonAnalysis, CareerPath, TranscriptAnalysisResult } from "../types";

// Define the model to use. 
// Using gemini-2.5-flash-latest as requested in system prompt mapping for "gemini flash"
const MODEL_NAME = 'gemini-2.5-flash-latest';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Schemas
const collegeSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    name: { type: Type.STRING },
    city: { type: Type.STRING },
    state: { type: Type.STRING },
    acceptanceRate: { type: Type.NUMBER, description: "Decimal value, e.g. 0.25 for 25%" },
    annualCost: { type: Type.NUMBER, description: "Average annual cost in USD" },
    description: { type: Type.STRING },
    reasonForFit: { type: Type.STRING },
    institutionType: { type: Type.STRING, enum: ['Public', 'Private', 'Liberal Arts', 'Technical', 'Other'] }
  },
  required: ['name', 'city', 'state', 'acceptanceRate', 'annualCost', 'description', 'reasonForFit', 'institutionType']
};

const collegeListSchema: Schema = {
  type: Type.ARRAY,
  items: collegeSchema
};

const comparisonSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    comparisons: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          collegeName: { type: Type.STRING },
          pros: { type: Type.ARRAY, items: { type: Type.STRING } },
          cons: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ['collegeName', 'pros', 'cons']
      }
    },
    costEffectiveness: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          collegeName: { type: Type.STRING },
          score: { type: Type.NUMBER, description: "Score from 0 to 100" },
          justification: { type: Type.STRING }
        },
        required: ['collegeName', 'score', 'justification']
      }
    },
    overallRecommendation: { type: Type.STRING }
  },
  required: ['comparisons', 'costEffectiveness', 'overallRecommendation']
};

const careerPathSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    careerTitle: { type: Type.STRING },
    potentialCareers: { type: Type.ARRAY, items: { type: Type.STRING } },
    keySkills: { type: Type.ARRAY, items: { type: Type.STRING } },
    salaryProjections: {
      type: Type.OBJECT,
      properties: {
        entryLevel: { type: Type.NUMBER },
        midLevel: { type: Type.NUMBER },
        seniorLevel: { type: Type.NUMBER }
      },
      required: ['entryLevel', 'midLevel', 'seniorLevel']
    },
    hiringCompanies: { type: Type.ARRAY, items: { type: Type.STRING } },
    networkingTips: { type: Type.ARRAY, items: { type: Type.STRING } },
    roadmap: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          stageName: { type: Type.STRING },
          description: { type: Type.STRING },
          actionItems: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ['stageName', 'description', 'actionItems']
      }
    }
  },
  required: ['careerTitle', 'potentialCareers', 'keySkills', 'salaryProjections', 'hiringCompanies', 'networkingTips', 'roadmap']
};

const transcriptAnalysisSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    inferredCareerGoal: { type: Type.STRING },
    suggestedDegrees: { type: Type.ARRAY, items: { type: Type.STRING } },
    suggestedColleges: { type: Type.ARRAY, items: collegeSchema }
  },
  required: ['inferredCareerGoal', 'suggestedDegrees', 'suggestedColleges']
};


// Services
export const findColleges = async (job: string, location: string): Promise<College[]> => {
  const prompt = `I want to be a ${job}. I am looking for colleges near ${location}. Suggest 6 colleges that are a good fit. Include public, private, and varied options.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: collegeListSchema,
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as College[];
    }
    return [];
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

export const findCollegesFromTranscript = async (base64Image: string, mimeType: string): Promise<TranscriptAnalysisResult | null> => {
  const prompt = "Analyze this academic transcript. Infer the student's strengths and potential career goals. Based on this, suggest 3 specific potential career paths and 4 colleges that would be a good fit for these strengths. Return valid JSON.";

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image
            }
          },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: transcriptAnalysisSchema
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as TranscriptAnalysisResult;
    }
    return null;
  } catch (error) {
    console.error("Gemini Transcript Error:", error);
    throw error;
  }
};

export const compareColleges = async (colleges: College[]): Promise<ComparisonAnalysis | null> => {
  const collegeNames = colleges.map(c => c.name).join(", ");
  const prompt = `Compare the following colleges: ${collegeNames}. Analyze pros/cons, cost effectiveness (ROI), and give an overall recommendation for a student interested in a balanced college experience.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: comparisonSchema
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as ComparisonAnalysis;
    }
    return null;
  } catch (error) {
    console.error("Gemini Compare Error:", error);
    throw error;
  }
};

export const getCareerPath = async (college: College, careerGoal: string): Promise<CareerPath | null> => {
  const prompt = `Create a detailed career roadmap for a student attending ${college.name} aiming to become a ${careerGoal}. Include salary projections, skills, and a timeline.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: careerPathSchema
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CareerPath;
    }
    return null;
  } catch (error) {
    console.error("Gemini Career Path Error:", error);
    throw error;
  }
};

export const getFinancialAidTips = async (): Promise<string[]> => {
    // Simple helper example - could be expanded to full JSON schema if needed
    // For brevity, using a simpler prompt or just returning static/mock for helpers if prompt not strictly required by user specs
    // But let's use AI for dynamic tips.
    const response = await ai.models.generateContent({
        model: MODEL_NAME,
        contents: "Give 5 top financial aid tips for US college students in JSON array format.",
        config: {
            responseMimeType: "application/json",
            responseSchema: { type: Type.ARRAY, items: { type: Type.STRING } }
        }
    });
    return response.text ? JSON.parse(response.text) : [];
}

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell } from 'recharts';

interface ChartProps {
  data: any[];
  dataKey: string;
  nameKey: string;
  color?: string;
  title: string;
  unit?: string;
}

const Chart: React.FC<ChartProps> = ({ data, dataKey, nameKey, color = "#4f46e5", title, unit = "" }) => {
  return (
    <div className="w-full h-64 bg-white p-4 rounded-xl shadow-sm border border-slate-100">
      <h3 className="text-sm font-semibold text-slate-700 mb-4">{title}</h3>
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={data}
          margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
        >
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
          <XAxis 
            dataKey={nameKey} 
            tick={{fontSize: 12, fill: '#64748b'}} 
            axisLine={false}
            tickLine={false}
          />
          <YAxis 
            tick={{fontSize: 12, fill: '#64748b'}} 
            axisLine={false}
            tickLine={false}
            tickFormatter={(value) => `${value}${unit}`}
          />
          <Tooltip 
            cursor={{fill: '#f1f5f9'}}
            contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
          />
          <Bar dataKey={dataKey} fill={color} radius={[4, 4, 0, 0]}>
            {data.map((entry, index) => (
               <Cell key={`cell-${index}`} fill={index % 2 === 0 ? color : `${color}cc`} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default Chart;

import React, { useState } from 'react';
import { logIn, signUp } from '../services/auth';
import { User } from '../types';
import { Lock, Mail, User as UserIcon, Loader2 } from 'lucide-react';

interface AuthViewProps {
  onLogin: (user: User) => void;
}

const AuthView: React.FC<AuthViewProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (isLogin) {
        const user = await logIn(email, password);
        onLogin(user);
      } else {
        const user = await signUp(name, email, password);
        onLogin(user);
      }
    } catch (err: any) {
      setError(err.message || 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 px-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl p-8 border border-slate-100">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-indigo-600 mb-2">NextStepFuture</h1>
          <p className="text-slate-500">{isLogin ? 'Welcome back, dreamer.' : 'Start your journey today.'}</p>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-red-50 text-red-600 text-sm rounded-lg flex items-center">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <div className="relative">
              <UserIcon className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
              <input
                type="text"
                placeholder="Full Name"
                className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required={!isLogin}
              />
            </div>
          )}

          <div className="relative">
            <Mail className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
            <input
              type="email"
              placeholder="Email Address"
              className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="relative">
            <Lock className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
            <input
              type="password"
              placeholder="Password"
              className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-3 rounded-lg transition duration-200 flex items-center justify-center"
          >
            {loading ? <Loader2 className="animate-spin h-5 w-5" /> : (isLogin ? 'Sign In' : 'Create Account')}
          </button>
        </form>

        <div className="mt-6 text-center text-sm text-slate-500">
          {isLogin ? "Don't have an account? " : "Already have an account? "}
          <button 
            onClick={() => setIsLogin(!isLogin)} 
            className="text-indigo-600 font-medium hover:underline focus:outline-none"
          >
            {isLogin ? 'Sign up' : 'Log in'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AuthView;

import React, { useState } from 'react';
import { findColleges, findCollegesFromTranscript } from '../services/gemini';
import { College, TranscriptAnalysisResult } from '../types';
import { Search, Upload, MapPin, Briefcase, Plus, Check, Loader2, FileText, X } from 'lucide-react';

interface SearchViewProps {
  onSaveCollege: (college: College) => void;
  savedCollegeNames: string[];
}

const SearchView: React.FC<SearchViewProps> = ({ onSaveCollege, savedCollegeNames }) => {
  const [activeTab, setActiveTab] = useState<'manual' | 'transcript'>('manual');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<College[]>([]);

  // Manual Search State
  const [job, setJob] = useState('');
  const [location, setLocation] = useState('');

  // Transcript State
  const [transcriptAnalysis, setTranscriptAnalysis] = useState<TranscriptAnalysisResult | null>(null);
  const [fileName, setFileName] = useState('');

  const handleManualSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!job || !location) return;
    setLoading(true);
    setResults([]);
    setTranscriptAnalysis(null);
    try {
      const colleges = await findColleges(job, location);
      setResults(colleges);
    } catch (error) {
      console.error(error);
      alert("Failed to fetch colleges. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleTranscriptUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileName(file.name);
    setLoading(true);
    setResults([]);
    setTranscriptAnalysis(null);

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      const mimeType = file.type;

      try {
        const analysis = await findCollegesFromTranscript(base64Data, mimeType);
        if (analysis) {
          setTranscriptAnalysis(analysis);
          setResults(analysis.suggestedColleges);
        }
      } catch (error) {
        console.error(error);
        alert("Failed to analyze transcript.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Tabs */}
      <div className="flex justify-center mb-8">
        <div className="bg-white p-1 rounded-xl shadow-sm border border-slate-200 inline-flex">
          <button
            onClick={() => setActiveTab('manual')}
            className={`px-6 py-2.5 rounded-lg text-sm font-medium transition-all ${
              activeTab === 'manual' 
                ? 'bg-indigo-600 text-white shadow-md' 
                : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Manual Search
          </button>
          <button
            onClick={() => setActiveTab('transcript')}
            className={`px-6 py-2.5 rounded-lg text-sm font-medium transition-all ${
              activeTab === 'transcript' 
                ? 'bg-indigo-600 text-white shadow-md' 
                : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Transcript Analysis
          </button>
        </div>
      </div>

      {/* Search Forms */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 mb-8 max-w-3xl mx-auto">
        {activeTab === 'manual' ? (
          <form onSubmit={handleManualSearch} className="flex flex-col md:flex-row gap-4">
            <div className="flex-1 relative">
              <Briefcase className="absolute left-3 top-3.5 h-5 w-5 text-slate-400" />
              <input
                type="text"
                placeholder="Career Goal (e.g. Data Scientist)"
                className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={job}
                onChange={(e) => setJob(e.target.value)}
              />
            </div>
            <div className="flex-1 relative">
              <MapPin className="absolute left-3 top-3.5 h-5 w-5 text-slate-400" />
              <input
                type="text"
                placeholder="Preferred Location (e.g. California)"
                className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={location}
                onChange={(e) => setLocation(e.target.value)}
              />
            </div>
            <button
              type="submit"
              disabled={loading}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3 rounded-lg font-medium transition flex items-center justify-center disabled:opacity-50"
            >
              {loading ? <Loader2 className="animate-spin h-5 w-5" /> : <Search className="h-5 w-5" />}
            </button>
          </form>
        ) : (
          <div className="text-center">
             <div className="border-2 border-dashed border-slate-300 rounded-xl p-8 hover:bg-slate-50 transition cursor-pointer relative">
                <input 
                  type="file" 
                  accept="image/*" 
                  onChange={handleTranscriptUpload}
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                />
                <div className="flex flex-col items-center">
                  <div className="bg-indigo-50 p-3 rounded-full mb-3">
                    <Upload className="h-6 w-6 text-indigo-600" />
                  </div>
                  <h3 className="text-sm font-semibold text-slate-900">
                    {fileName ? fileName : 'Upload Transcript Image'}
                  </h3>
                  <p className="text-xs text-slate-500 mt-1">
                    {fileName ? 'Click to change file' : 'PNG, JPG up to 5MB. AI will analyze your strengths.'}
                  </p>
                </div>
             </div>
             {loading && <div className="mt-4 flex justify-center text-sm text-indigo-600 items-center gap-2"><Loader2 className="animate-spin h-4 w-4"/> Analyzing transcript...</div>}
          </div>
        )}
      </div>

      {/* Transcript Insights */}
      {transcriptAnalysis && (
        <div className="mb-8 p-6 bg-gradient-to-r from-indigo-50 to-purple-50 rounded-2xl border border-indigo-100">
          <h3 className="text-lg font-bold text-indigo-900 mb-2 flex items-center gap-2">
            <FileText className="h-5 w-5"/> AI Insights
          </h3>
          <div className="grid md:grid-cols-2 gap-4 text-sm">
            <div>
              <span className="font-semibold text-indigo-700">Inferred Goal:</span>
              <p className="text-slate-700">{transcriptAnalysis.inferredCareerGoal}</p>
            </div>
            <div>
              <span className="font-semibold text-indigo-700">Suggested Degrees:</span>
              <div className="flex flex-wrap gap-2 mt-1">
                {transcriptAnalysis.suggestedDegrees.map((d, i) => (
                  <span key={i} className="bg-white px-2 py-1 rounded text-indigo-600 border border-indigo-100 text-xs font-medium">{d}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Results Grid */}
      {results.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {results.map((college, idx) => {
            const isSaved = savedCollegeNames.includes(college.name);
            return (
              <div key={idx} className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden hover:shadow-md transition-shadow flex flex-col">
                <div className="p-5 flex-1">
                  <div className="flex justify-between items-start mb-2">
                    <span className="inline-block px-2 py-1 rounded-full bg-slate-100 text-slate-600 text-xs font-medium">
                      {college.institutionType}
                    </span>
                    <span className="text-xs font-medium text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">
                       {(college.acceptanceRate * 100).toFixed(0)}% Acceptance
                    </span>
                  </div>
