import React, { useState } from 'react';
import { College, ComparisonAnalysis } from '../types';
import { compareColleges } from '../services/gemini';
import { Trash2, BarChart2, CheckSquare, Square, Zap, DollarSign } from 'lucide-react';
import Chart from './Chart';

interface SavedCollegesViewProps {
  colleges: College[];
  onRemove: (name: string) => void;
  onSetCareerCollege: (college: College) => void;
}

const SavedCollegesView: React.FC<SavedCollegesViewProps> = ({ colleges, onRemove, onSetCareerCollege }) => {
  const [selected, setSelected] = useState<string[]>([]);
  const [analysis, setAnalysis] = useState<ComparisonAnalysis | null>(null);
  const [loading, setLoading] = useState(false);

  const toggleSelect = (name: string) => {
    setSelected(prev => prev.includes(name) ? prev.filter(n => n !== name) : [...prev, name]);
  };

  const handleCompare = async () => {
    if (selected.length < 2) return;
    setLoading(true);
    setAnalysis(null);
    try {
      const selectedColleges = colleges.filter(c => selected.includes(c.name));
      const result = await compareColleges(selectedColleges);
      setAnalysis(result);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  if (colleges.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh] text-slate-400">
        <CheckSquare className="h-16 w-16 mb-4 opacity-20" />
        <p>No colleges saved yet. Start searching!</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-900">Your College List</h2>
        <button
          onClick={handleCompare}
          disabled={selected.length < 2 || loading}
          className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white px-5 py-2 rounded-lg text-sm font-medium transition flex items-center gap-2"
        >
          {loading ? 'Analyzing...' : <><BarChart2 className="h-4 w-4" /> Compare ({selected.length})</>}
        </button>
      </div>

      {/* List */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden mb-8">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-slate-600">
            <thead className="bg-slate-50 text-slate-900 font-semibold uppercase text-xs">
              <tr>
                <th className="p-4 w-12">Select</th>
                <th className="p-4">College</th>
                <th className="p-4">Location</th>
                <th className="p-4">Cost/Yr</th>
                <th className="p-4">Acceptance</th>
                <th className="p-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {colleges.map((c) => (
                <tr key={c.name} className="hover:bg-slate-50 transition">
                  <td className="p-4">
                    <button onClick={() => toggleSelect(c.name)} className="text-indigo-600">
                      {selected.includes(c.name) ? <CheckSquare className="h-5 w-5"/> : <Square className="h-5 w-5 text-slate-300"/>}
                    </button>
                  </td>
                  <td className="p-4 font-medium text-slate-900">{c.name}</td>
                  <td className="p-4">{c.city}, {c.state}</td>
                  <td className="p-4">${c.annualCost.toLocaleString()}</td>
                  <td className="p-4">{(c.acceptanceRate * 100).toFixed(1)}%</td>
                  <td className="p-4 text-right flex justify-end gap-2">
                    <button 
                      onClick={() => onSetCareerCollege(c)}
                      className="text-indigo-600 hover:text-indigo-800 text-xs font-medium px-2 py-1 rounded hover:bg-indigo-50"
                    >
                      Plan Career
                    </button>
                    <button 
                      onClick={() => onRemove(c.name)}
                      className="text-red-400 hover:text-red-600"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Analysis Section */}
      {analysis && (
        <div className="space-y-6 animate-fade-in">
          <div className="grid md:grid-cols-2 gap-6">
            <Chart 
              title="Annual Cost Comparison" 
              data={colleges.filter(c => selected.includes(c.name)).map(c => ({ name: c.name, cost: c.annualCost }))}
              dataKey="cost"
              nameKey="name"
              color="#6366f1"
              unit="$"
            />
             <Chart 
              title="Acceptance Rate" 
              data={colleges.filter(c => selected.includes(c.name)).map(c => ({ name: c.name, rate: parseFloat((c.acceptanceRate * 100).toFixed(1)) }))}
              dataKey="rate"
              nameKey="name"
              color="#10b981"
              unit="%"
            />
          </div>

          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
            <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
              <Zap className="h-5 w-5 text-yellow-500"/> AI Recommendation
            </h3>
            <p className="text-slate-700 mb-6 bg-yellow-50 p-4 rounded-lg border border-yellow-100">
              {analysis.overallRecommendation}
            </p>

            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
              {analysis.comparisons.map((comp, idx) => (
                <div key={idx} className="bg-slate-50 rounded-xl p-4 border border-slate-100">
                  <h4 className="font-bold text-slate-900 mb-2">{comp.collegeName}</h4>
                  <div className="mb-3">
                    <h5 className="text-xs font-semibold text-green-600 uppercase tracking-wide mb-1">Pros</h5>
                    <ul className="text-sm text-slate-600 list-disc list-inside">
                      {comp.pros.map((p, i) => <li key={i}>{p}</li>)}
                    </ul>
                  </div>
                  <div>
                    <h5 className="text-xs font-semibold text-red-500 uppercase tracking-wide mb-1">Cons</h5>
                    <ul className="text-sm text-slate-600 list-disc list-inside">
                      {comp.cons.map((c, i) => <li key={i}>{c}</li>)}
