            <div className="mt-8">
              <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                 <DollarSign className="h-5 w-5 text-green-600"/> Cost Effectiveness Scores
              </h3>
              <div className="space-y-4">
                {analysis.costEffectiveness.map((item, idx) => (
                   <div key={idx}>
                      <div className="flex justify-between text-sm mb-1">
                        <span className="font-medium">{item.collegeName}</span>
                        <span className="font-bold text-slate-700">{item.score}/100</span>
                      </div>
                      <div className="w-full bg-slate-100 rounded-full h-2.5 mb-1">
                        <div className="bg-green-500 h-2.5 rounded-full" style={{ width: `${item.score}%` }}></div>
                      </div>
                      <p className="text-xs text-slate-500">{item.justification}</p>
                   </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SavedCollegesView;

import React, { useState, useEffect } from 'react';
