                   <span key={i} className="bg-indigo-50 text-indigo-700 text-xs px-2 py-1 rounded font-medium">{skill}</span>
                 ))}
                 {path.keySkills.length > 4 && <span className="text-xs text-slate-400">+{path.keySkills.length - 4} more</span>}
