            </div>
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
               <h3 className="text-sm font-semibold text-slate-500 mb-2">Top Employers</h3>
               <div className="text-sm text-slate-700 space-y-1">
