import React, { useState, useEffect } from 'react';
import { User, College } from './types';
import { getSession, logOut } from './services/auth';
import AuthView from './components/AuthView';
import SearchView from './components/SearchView';
import SavedCollegesView from './components/SavedCollegesView';
import CareerPathView from './components/CareerPathView';
import { LayoutDashboard, BookOpen, Compass, LogOut, GraduationCap } from 'lucide-react';

type View = 'search' | 'saved' | 'career';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<View>('search');
  const [savedColleges, setSavedColleges] = useState<College[]>([]);
  const [careerCollege, setCareerCollege] = useState<College | null>(null);

  useEffect(() => {
    // Check auth
    const session = getSession();
    if (session) setUser(session);

    // Load saved colleges
    const saved = localStorage.getItem('nsf_saved_colleges');
    if (saved) setSavedColleges(JSON.parse(saved));
  }, []);

  useEffect(() => {
    if (user) {
      localStorage.setItem('nsf_saved_colleges', JSON.stringify(savedColleges));
    }
  }, [savedColleges, user]);

  const handleLogout = () => {
    logOut();
    setUser(null);
    setView('search');
    setSavedColleges([]);
  };

  const saveCollege = (college: College) => {
    if (!savedColleges.some(c => c.name === college.name)) {
      setSavedColleges([...savedColleges, college]);
    }
  };

  const removeCollege = (name: string) => {
    setSavedColleges(savedColleges.filter(c => c.name !== name));
  };

  const navigateToCareer = (college: College) => {
    setCareerCollege(college);
    setView('career');
  };

  if (!user) {
    return <AuthView onLogin={setUser} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Navigation */}
      <nav className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center gap-2">
              <div className="bg-indigo-600 p-1.5 rounded-lg">
                <GraduationCap className="h-6 w-6 text-white" />
              </div>
              <span className="font-bold text-xl text-slate-900 hidden md:block">NextStepFuture</span>
            </div>

            <div className="flex space-x-1 overflow-x-auto no-scrollbar items-center">
              <button
                onClick={() => setView('search')}
                className={`px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition ${view === 'search' ? 'bg-indigo-50 text-indigo-700' : 'text-slate-600 hover:text-slate-900'}`}
              >
                <LayoutDashboard className="h-4 w-4" /> Search
              </button>
              <button
                onClick={() => setView('saved')}
                className={`px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition ${view === 'saved' ? 'bg-indigo-50 text-indigo-700' : 'text-slate-600 hover:text-slate-900'}`}
              >
                <BookOpen className="h-4 w-4" /> Saved <span className="bg-slate-200 text-slate-600 text-xs px-1.5 py-0.5 rounded-full">{savedColleges.length}</span>
              </button>
              <button
                onClick={() => setView('career')}
                className={`px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition ${view === 'career' ? 'bg-indigo-50 text-indigo-700' : 'text-slate-600 hover:text-slate-900'}`}
              >
                <Compass className="h-4 w-4" /> Career Path
              </button>
            </div>

            <div className="flex items-center">
              <button onClick={handleLogout} className="text-slate-400 hover:text-slate-600 p-2">
                <LogOut className="h-5 w-5" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1">
        {view === 'search' && (
          <SearchView 
            onSaveCollege={saveCollege} 
            savedCollegeNames={savedColleges.map(c => c.name)} 
          />
        )}
        {view === 'saved' && (
          <SavedCollegesView 
            colleges={savedColleges} 
            onRemove={removeCollege}
            onSetCareerCollege={navigateToCareer}
          />
        )}
        {view === 'career' && (
          <CareerPathView initialCollege={careerCollege} />
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { College, ComparisonAnalysis, CareerPath, TranscriptAnalysisResult } from "../types";

// Using gemini-3-flash-preview as reliable model for text and multimodal tasks
const MODEL_NAME = 'gemini-3-flash-preview';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Schemas
const collegeSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    name: { type: Type.STRING },
    city: { type: Type.STRING },
    state: { type: Type.STRING },
    acceptanceRate: { type: Type.NUMBER, description: "Decimal value, e.g. 0.25 for 25%" },
    annualCost: { type: Type.NUMBER, description: "Average annual cost in USD" },
    description: { type: Type.STRING },
    reasonForFit: { type: Type.STRING },
    institutionType: { type: Type.STRING, enum: ['Public', 'Private', 'Liberal Arts', 'Technical', 'Other'] }
  },
  required: ['name', 'city', 'state', 'acceptanceRate', 'annualCost', 'description', 'reasonForFit', 'institutionType']
};

const collegeListSchema: Schema = {
  type: Type.ARRAY,
  items: collegeSchema
};

const comparisonSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    comparisons: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          collegeName: { type: Type.STRING },
          pros: { type: Type.ARRAY, items: { type: Type.STRING } },
          cons: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ['collegeName', 'pros', 'cons']
      }
    },
    costEffectiveness: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          collegeName: { type: Type.STRING },
          score: { type: Type.NUMBER, description: "Score from 0 to 100" },
          justification: { type: Type.STRING }
        },
        required: ['collegeName', 'score', 'justification']
      }
    },
    overallRecommendation: { type: Type.STRING }
  },
  required: ['comparisons', 'costEffectiveness', 'overallRecommendation']
};

const careerPathSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    careerTitle: { type: Type.STRING },
    potentialCareers: { type: Type.ARRAY, items: { type: Type.STRING } },
    keySkills: { type: Type.ARRAY, items: { type: Type.STRING } },
    salaryProjections: {
      type: Type.OBJECT,
      properties: {
        entryLevel: { type: Type.NUMBER },
        midLevel: { type: Type.NUMBER },
        seniorLevel: { type: Type.NUMBER }
      },
      required: ['entryLevel', 'midLevel', 'seniorLevel']
    },
    hiringCompanies: { type: Type.ARRAY, items: { type: Type.STRING } },
    networkingTips: { type: Type.ARRAY, items: { type: Type.STRING } },
    roadmap: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          stageName: { type: Type.STRING },
          description: { type: Type.STRING },
          actionItems: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ['stageName', 'description', 'actionItems']
      }
    }
  },
  required: ['careerTitle', 'potentialCareers', 'keySkills', 'salaryProjections', 'hiringCompanies', 'networkingTips', 'roadmap']
};

const transcriptAnalysisSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    inferredCareerGoal: { type: Type.STRING },
    suggestedDegrees: { type: Type.ARRAY, items: { type: Type.STRING } },
    suggestedColleges: { type: Type.ARRAY, items: collegeSchema }
  },
  required: ['inferredCareerGoal', 'suggestedDegrees', 'suggestedColleges']
};


// Services
export const findColleges = async (job: string, location: string): Promise<College[]> => {
  const prompt = `I want to be a ${job}. I am looking for colleges near ${location}. Suggest 6 colleges that are a good fit. Include public, private, and varied options.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: collegeListSchema,
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as College[];
    }
    return [];
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

export const findCollegesFromTranscript = async (base64Image: string, mimeType: string): Promise<TranscriptAnalysisResult | null> => {
  const prompt = "Analyze this academic transcript. Infer the student's strengths and potential career goals. Based on this, suggest 3 specific potential career paths and 4 colleges that would be a good fit for these strengths. Return valid JSON.";

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image
            }
          },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: transcriptAnalysisSchema
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as TranscriptAnalysisResult;
    }
    return null;
  } catch (error) {
    console.error("Gemini Transcript Error:", error);
    throw error;
  }
};

export const compareColleges = async (colleges: College[]): Promise<ComparisonAnalysis | null> => {
  const collegeNames = colleges.map(c => c.name).join(", ");
  const prompt = `Compare the following colleges: ${collegeNames}. Analyze pros/cons, cost effectiveness (ROI), and give an overall recommendation for a student interested in a balanced college experience.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: comparisonSchema
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as ComparisonAnalysis;
    }
    return null;
  } catch (error) {
    console.error("Gemini Compare Error:", error);
    throw error;
  }
};

