import React, { useState } from 'react';
import { findColleges, findCollegesFromTranscript } from '../services/gemini';
import { College, TranscriptAnalysisResult } from '../types';
import { Search, Upload, MapPin, Briefcase, Plus, Check, Loader2, FileText, DollarSign, BookOpen, Star, Sparkles } from 'lucide-react';

interface SearchViewProps {
  onSaveCollege: (college: College) => void;
  savedCollegeNames: string[];
}

const SearchView: React.FC<SearchViewProps> = ({ onSaveCollege, savedCollegeNames }) => {
  const [activeTab, setActiveTab] = useState<'manual' | 'transcript'>('manual');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<College[]>([]);

  // Manual Search State
  const [job, setJob] = useState('');
  const [location, setLocation] = useState('');

  // Transcript State
  const [transcriptAnalysis, setTranscriptAnalysis] = useState<TranscriptAnalysisResult | null>(null);
  const [fileName, setFileName] = useState('');

  const handleManualSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!job || !location) return;
    setLoading(true);
    setResults([]);
    setTranscriptAnalysis(null);
    try {
      const colleges = await findColleges(job, location);
      setResults(colleges);
    } catch (error) {
      console.error(error);
      alert("Failed to fetch colleges. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleTranscriptUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileName(file.name);
    setLoading(true);
    setResults([]);
    setTranscriptAnalysis(null);

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      const mimeType = file.type;

      try {
        const analysis = await findCollegesFromTranscript(base64Data, mimeType);
        if (analysis) {
          setTranscriptAnalysis(analysis);
          setResults(analysis.suggestedColleges);
        }
      } catch (error) {
        console.error(error);
        alert("Failed to analyze transcript.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const getFitIndicator = (reason: string) => {
    const r = reason.toLowerCase();
    if (r.includes('cost') || r.includes('afford') || r.includes('financial') || r.includes('tuition')) {
      return { icon: DollarSign, color: 'text-emerald-600 bg-emerald-50 border-emerald-100', label: 'Financial Fit' };
    }
    if (r.includes('location') || r.includes('near') || r.includes('city') || r.includes('close')) {
      return { icon: MapPin, color: 'text-blue-600 bg-blue-50 border-blue-100', label: 'Location Fit' };
    }
    if (r.includes('academic') || r.includes('program') || r.includes('major') || r.includes('rank')) {
      return { icon: BookOpen, color: 'text-purple-600 bg-purple-50 border-purple-100', label: 'Academic Fit' };
    }
    if (r.includes('career') || r.includes('job') || r.includes('employ') || r.includes('industry')) {
      return { icon: Briefcase, color: 'text-amber-600 bg-amber-50 border-amber-100', label: 'Career Fit' };
    }
    if (r.includes('culture') || r.includes('life') || r.includes('social') || r.includes('vibe')) {
      return { icon: Sparkles, color: 'text-pink-600 bg-pink-50 border-pink-100', label: 'Cultural Fit' };
    }
    return { icon: Star, color: 'text-indigo-600 bg-indigo-50 border-indigo-100', label: 'Overall Fit' };
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Tabs */}
      <div className="flex justify-center mb-8">
        <div className="bg-white p-1 rounded-xl shadow-sm border border-slate-200 inline-flex">
          <button
            onClick={() => setActiveTab('manual')}
            className={`px-6 py-2.5 rounded-lg text-sm font-medium transition-all ${
              activeTab === 'manual' 
                ? 'bg-indigo-600 text-white shadow-md' 
                : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Manual Search
          </button>
          <button
            onClick={() => setActiveTab('transcript')}
            className={`px-6 py-2.5 rounded-lg text-sm font-medium transition-all ${
              activeTab === 'transcript' 
                ? 'bg-indigo-600 text-white shadow-md' 
                : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Transcript Analysis
          </button>
        </div>
      </div>

      {/* Search Forms */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 mb-8 max-w-3xl mx-auto">
        {activeTab === 'manual' ? (
          <form onSubmit={handleManualSearch} className="flex flex-col md:flex-row gap-4">
            <div className="flex-1 relative">
              <Briefcase className="absolute left-3 top-3.5 h-5 w-5 text-slate-400" />
              <input
                type="text"
                placeholder="Career Goal (e.g. Data Scientist)"
                className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={job}
                onChange={(e) => setJob(e.target.value)}
              />
            </div>
            <div className="flex-1 relative">
              <MapPin className="absolute left-3 top-3.5 h-5 w-5 text-slate-400" />
              <input
                type="text"
                placeholder="Preferred Location (e.g. California)"
                className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={location}
                onChange={(e) => setLocation(e.target.value)}
              />
            </div>
            <button
              type="submit"
              disabled={loading}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3 rounded-lg font-medium transition flex items-center justify-center disabled:opacity-50"
            >
              {loading ? <Loader2 className="animate-spin h-5 w-5" /> : <Search className="h-5 w-5" />}
            </button>
          </form>
        ) : (
          <div className="text-center">
             <div className="border-2 border-dashed border-slate-300 rounded-xl p-8 hover:bg-slate-50 transition cursor-pointer relative">
                <input 
                  type="file" 
                  accept="image/*" 
                  onChange={handleTranscriptUpload}
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                />
                <div className="flex flex-col items-center">
                  <div className="bg-indigo-50 p-3 rounded-full mb-3">
                    <Upload className="h-6 w-6 text-indigo-600" />
                  </div>
                  <h3 className="text-sm font-semibold text-slate-900">
                    {fileName ? fileName : 'Upload Transcript Image'}
                  </h3>
                  <p className="text-xs text-slate-500 mt-1">
                    {fileName ? 'Click to change file' : 'PNG, JPG up to 5MB. AI will analyze your strengths.'}
                  </p>
                </div>
             </div>
             {loading && <div className="mt-4 flex justify-center text-sm text-indigo-600 items-center gap-2"><Loader2 className="animate-spin h-4 w-4"/> Analyzing transcript...</div>}
          </div>
        )}
      </div>

      {/* Transcript Insights */}
      {transcriptAnalysis && (
        <div className="mb-8 p-6 bg-gradient-to-r from-indigo-50 to-purple-50 rounded-2xl border border-indigo-100">
          <h3 className="text-lg font-bold text-indigo-900 mb-2 flex items-center gap-2">
            <FileText className="h-5 w-5"/> AI Insights
          </h3>
          <div className="grid md:grid-cols-2 gap-4 text-sm">
            <div>
              <span className="font-semibold text-indigo-700">Inferred Goal:</span>
              <p className="text-slate-700">{transcriptAnalysis.inferredCareerGoal}</p>
            </div>
            <div>
              <span className="font-semibold text-indigo-700">Suggested Degrees:</span>
              <div className="flex flex-wrap gap-2 mt-1">
                {transcriptAnalysis.suggestedDegrees.map((d, i) => (
                  <span key={i} className="bg-white px-2 py-1 rounded text-indigo-600 border border-indigo-100 text-xs font-medium">{d}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Results Grid */}
      {results.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {results.map((college, idx) => {
            const isSaved = savedCollegeNames.includes(college.name);
            const fitIndicator = getFitIndicator(college.reasonForFit);
            const FitIcon = fitIndicator.icon;

            return (
              <div key={idx} className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden hover:shadow-md transition-shadow flex flex-col group">
                <div className="p-5 flex-1 flex flex-col">
                  <div className="flex justify-between items-start mb-2">
                    <span className="inline-block px-2 py-1 rounded-full bg-slate-100 text-slate-600 text-xs font-medium">
                      {college.institutionType}
                    </span>
                    <span className="text-xs font-medium text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">
                       {(college.acceptanceRate * 100).toFixed(0)}% Acceptance
                    </span>
                  </div>
                  <h3 className="text-lg font-bold text-slate-900 mb-1 group-hover:text-indigo-600 transition-colors">{college.name}</h3>
                  <p className="text-sm text-slate-500 flex items-center gap-1 mb-3">
                    <MapPin className="h-3 w-3" /> {college.city}, {college.state}
                  </p>
                  <p className="text-sm text-slate-600 mb-4 line-clamp-3 flex-1">{college.description}</p>

                  {/* Visual Fit Indicator */}
                  <div className={`mt-auto rounded-lg border p-3 flex gap-3 ${fitIndicator.color}`}>
                    <div className="mt-0.5">
                      <FitIcon className="h-5 w-5" />
                    </div>
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-wider opacity-80 mb-0.5">{fitIndicator.label}</p>
                      <p className="text-sm font-medium leading-snug">{college.reasonForFit}</p>
                    </div>
                  </div>
                </div>

                <div className="p-4 border-t border-slate-100 flex items-center justify-between bg-slate-50">
                  <div className="text-sm font-bold text-slate-900">
                    ${college.annualCost.toLocaleString()}<span className="text-xs font-normal text-slate-500">/yr</span>
                  </div>
                  <button
                    onClick={() => !isSaved && onSaveCollege(college)}
                    disabled={isSaved}
                    className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium transition ${
                      isSaved 
                        ? 'bg-green-100 text-green-700 cursor-default' 
                        : 'bg-indigo-600 text-white hover:bg-indigo-700'
                    }`}
                  >
                    {isSaved ? <><Check className="h-3 w-3" /> Saved</> : <><Plus className="h-3 w-3" /> Save</>}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default SearchView;

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface ChartProps {
  data: any[];
  dataKey: string;
  nameKey: string;
  color?: string;
  title: string;
  unit?: string;
  darkMode?: boolean;
}

const Chart: React.FC<ChartProps> = ({ data, dataKey, nameKey, color = "#4f46e5", title, unit = "", darkMode = false }) => {
  const textColor = darkMode ? '#94a3b8' : '#64748b';
  const gridColor = darkMode ? '#334155' : '#e2e8f0';
  const tooltipBg = darkMode ? '#1e293b' : '#ffffff';
  const tooltipText = darkMode ? '#f8fafc' : '#0f172a';

  return (
    <div className="w-full h-64 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 transition-colors">
      <h3 className="text-sm font-semibold text-slate-700 dark:text-slate-200 mb-4">{title}</h3>
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={data}
          margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
        >
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={gridColor} />
          <XAxis 
            dataKey={nameKey} 
            tick={{fontSize: 12, fill: textColor}} 
            axisLine={false}
            tickLine={false}
          />
          <YAxis 
            tick={{fontSize: 12, fill: textColor}} 
            axisLine={false}
            tickLine={false}
            tickFormatter={(value) => `${value}${unit}`}
          />
          <Tooltip 
            cursor={{fill: darkMode ? '#334155' : '#f1f5f9'}}
            contentStyle={{ 
              borderRadius: '8px', 
              border: 'none', 
              boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
              backgroundColor: tooltipBg,
              color: tooltipText
            }}
          />
          <Bar dataKey={dataKey} fill={color} radius={[4, 4, 0, 0]}>
            {data.map((entry, index) => (
               <Cell key={`cell-${index}`} fill={index % 2 === 0 ? color : `${color}cc`} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default Chart;

import React, { useState } from 'react';
import { logIn, signUp } from '../services/auth';
import { User } from '../types';
import { Lock, Mail, User as UserIcon, Loader2 } from 'lucide-react';

interface AuthViewProps {
  onLogin: (user: User) => void;
}

const AuthView: React.FC<AuthViewProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (isLogin) {
        const user = await logIn(email, password);
        onLogin(user);
      } else {
        const user = await signUp(name, email, password);
        onLogin(user);
      }
    } catch (err: any) {
      setError(err.message || 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 px-4 transition-colors">
      <div className="max-w-md w-full bg-white dark:bg-slate-800 rounded-2xl shadow-xl p-8 border border-slate-100 dark:border-slate-700 transition-colors">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-indigo-600 dark:text-indigo-400 mb-2">NextStepFuture</h1>
          <p className="text-slate-500 dark:text-slate-400">{isLogin ? 'Welcome back, dreamer.' : 'Start your journey today.'}</p>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-red-50 dark:bg-red-900/30 text-red-600 dark:text-red-400 text-sm rounded-lg flex items-center border border-red-100 dark:border-red-900/50">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <div className="relative">
              <UserIcon className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
              <input
                type="text"
                placeholder="Full Name"
                className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required={!isLogin}
              />
            </div>
          )}

          <div className="relative">
            <Mail className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
            <input
              type="email"
              placeholder="Email Address"
              className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="relative">
            <Lock className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
            <input
              type="password"
              placeholder="Password"
              className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600 text-white font-semibold py-3 rounded-lg transition duration-200 flex items-center justify-center"
          >
            {loading ? <Loader2 className="animate-spin h-5 w-5" /> : (isLogin ? 'Sign In' : 'Create Account')}
          </button>
        </form>

        <div className="mt-6 text-center text-sm text-slate-500 dark:text-slate-400">
          {isLogin ? "Don't have an account? " : "Already have an account? "}
          <button 
            onClick={() => setIsLogin(!isLogin)} 
            className="text-indigo-600 dark:text-indigo-400 font-medium hover:underline focus:outline-none"
          >
            {isLogin ? 'Sign up' : 'Log in'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AuthView;

