import React, { useState, useEffect } from 'react';
import { User, College } from './types';
import { getSession, logOut } from './services/auth';
import AuthView from './components/AuthView';
import SearchView from './components/SearchView';
import SavedCollegesView from './components/SavedCollegesView';
import CareerPathView from './components/CareerPathView';
import { LayoutDashboard, BookOpen, Compass, LogOut, GraduationCap, Moon, Sun } from 'lucide-react';

type View = 'search' | 'saved' | 'career';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<View>('search');
  const [savedColleges, setSavedColleges] = useState<College[]>([]);
  const [careerCollege, setCareerCollege] = useState<College | null>(null);

  // Theme State initialization
  const [isDarkMode, setIsDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
      const savedTheme = localStorage.getItem('nsf_theme');
      if (savedTheme) {
        return savedTheme === 'dark';
      }
      return window.matchMedia('(prefers-color-scheme: dark)').matches;
    }
    return false;
  });

  // Apply theme class to html element
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('nsf_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('nsf_theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => {
    // Check auth
    const session = getSession();
    if (session) setUser(session);

    // Load saved colleges
    const saved = localStorage.getItem('nsf_saved_colleges');
    if (saved) setSavedColleges(JSON.parse(saved));
  }, []);

  useEffect(() => {
    if (user) {
      localStorage.setItem('nsf_saved_colleges', JSON.stringify(savedColleges));
    }
  }, [savedColleges, user]);

  const handleLogout = () => {
    logOut();
    setUser(null);
    setView('search');
    setSavedColleges([]);
  };

  const saveCollege = (college: College) => {
    if (!savedColleges.some(c => c.name === college.name)) {
      setSavedColleges([...savedColleges, college]);
    }
  };

  const removeCollege = (name: string) => {
    setSavedColleges(savedColleges.filter(c => c.name !== name));
  };

  const navigateToCareer = (college: College) => {
    setCareerCollege(college);
    setView('career');
  };

  const toggleTheme = () => {
    setIsDarkMode(!isDarkMode);
  };

  if (!user) {
    return <AuthView onLogin={setUser} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col transition-colors duration-200">
      {/* Navigation */}
      <nav className="bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-50 transition-colors">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center gap-2">
              <div className="bg-indigo-600 p-1.5 rounded-lg">
                <GraduationCap className="h-6 w-6 text-white" />
              </div>
              <span className="font-bold text-xl text-slate-900 dark:text-white hidden md:block">NextStepFuture</span>
            </div>

            <div className="flex space-x-1 overflow-x-auto no-scrollbar items-center">
              <button
                onClick={() => setView('search')}
                className={`px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition ${view === 'search' ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-400' : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'}`}
              >
                <LayoutDashboard className="h-4 w-4" /> Search
              </button>
              <button
                onClick={() => setView('saved')}
                className={`px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition ${view === 'saved' ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-400' : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'}`}
              >
                <BookOpen className="h-4 w-4" /> Saved <span className="bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs px-1.5 py-0.5 rounded-full">{savedColleges.length}</span>
              </button>
              <button
                onClick={() => setView('career')}
                className={`px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition ${view === 'career' ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-400' : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'}`}
              >
                <Compass className="h-4 w-4" /> Career Path
              </button>
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={toggleTheme}
                className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition"
                title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
              >
                {isDarkMode ? <Sun className="h-5 w-5" /> : <Moon className="h-5 w-5" />}
              </button>
              <div className="h-6 w-px bg-slate-200 dark:bg-slate-700 mx-1"></div>
              <button onClick={handleLogout} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition" title="Log Out">
                <LogOut className="h-5 w-5" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1">
        {view === 'search' && (
          <SearchView 
            onSaveCollege={saveCollege} 
            savedCollegeNames={savedColleges.map(c => c.name)} 
          />
        )}
        {view === 'saved' && (
          <SavedCollegesView 
            colleges={savedColleges} 
            onRemove={removeCollege}
            onSetCareerCollege={navigateToCareer}
            darkMode={isDarkMode}
          />
        )}
        {view === 'career' && (
          <CareerPathView initialCollege={careerCollege} darkMode={isDarkMode} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { logIn, signUp } from '../services/auth';
import { User } from '../types';
import { Lock, Mail, User as UserIcon, Loader2, Moon, Sun } from 'lucide-react';

interface AuthViewProps {
  onLogin: (user: User) => void;
  isDarkMode: boolean;
  onToggleTheme: () => void;
}

const AuthView: React.FC<AuthViewProps> = ({ onLogin, isDarkMode, onToggleTheme }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (isLogin) {
        const user = await logIn(email, password);
        onLogin(user);
      } else {
        const user = await signUp(name, email, password);
        onLogin(user);
      }
    } catch (err: any) {
      setError(err.message || 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 px-4 transition-colors relative">
      <button 
        onClick={onToggleTheme}
        className="absolute top-6 right-6 p-2 rounded-full bg-white dark:bg-slate-800 shadow-sm border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 transition-colors"
        title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
      >
        {isDarkMode ? <Sun className="h-5 w-5" /> : <Moon className="h-5 w-5" />}
      </button>

      <div className="max-w-md w-full bg-white dark:bg-slate-800 rounded-2xl shadow-xl p-8 border border-slate-100 dark:border-slate-700 transition-colors">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-indigo-600 dark:text-indigo-400 mb-2">NextStepFuture</h1>
          <p className="text-slate-500 dark:text-slate-400">{isLogin ? 'Welcome back, dreamer.' : 'Start your journey today.'}</p>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-red-50 dark:bg-red-900/30 text-red-600 dark:text-red-400 text-sm rounded-lg flex items-center border border-red-100 dark:border-red-900/50">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <div className="relative">
              <UserIcon className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
              <input
                type="text"
                placeholder="Full Name"
                className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required={!isLogin}
              />
            </div>
          )}

          <div className="relative">
            <Mail className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
            <input
              type="email"
              placeholder="Email Address"
              className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="relative">
            <Lock className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
            <input
              type="password"
              placeholder="Password"
              className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600 text-white font-semibold py-3 rounded-lg transition duration-200 flex items-center justify-center"
          >
            {loading ? <Loader2 className="animate-spin h-5 w-5" /> : (isLogin ? 'Sign In' : 'Create Account')}
          </button>
        </form>

        <div className="mt-6 text-center text-sm text-slate-500 dark:text-slate-400">
          {isLogin ? "Don't have an account? " : "Already have an account? "}
          <button 
            onClick={() => setIsLogin(!isLogin)} 
            className="text-indigo-600 dark:text-indigo-400 font-medium hover:underline focus:outline-none"
          >
            {isLogin ? 'Sign up' : 'Log in'}
          </button>
        </div>
      </div>
    </div>
  );
};

