              </div>
              <span className="font-bold text-xl text-slate-900 dark:text-white hidden md:block">NextStepFuture</span>
            </div>

            {/* Center Navigation - Scrollable on mobile */}
            <div className="flex-1 flex justify-center min-w-0 mx-2 md:mx-4">
              <div className="flex space-x-1 overflow-x-auto no-scrollbar items-center py-1 max-w-full">
                <button
                  onClick={() => setView('search')}
                  className={`px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 whitespace-nowrap transition ${view === 'search' ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-400' : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'}`}
                >
                  <LayoutDashboard className="h-4 w-4" /> Search
                </button>
                <button
                  onClick={() => setView('saved')}
                  className={`px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 whitespace-nowrap transition ${view === 'saved' ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-400' : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'}`}
                >
                  <BookOpen className="h-4 w-4" /> Saved <span className="bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs px-1.5 py-0.5 rounded-full">{savedColleges.length}</span>
                </button>
                <button
                  onClick={() => setView('career')}
                  className={`px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 whitespace-nowrap transition ${view === 'career' ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-400' : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'}`}
                >
                  <Compass className="h-4 w-4" /> Career Path
                </button>
              </div>
            </div>

            <div className="flex items-center gap-2 shrink-0">
              <button 
                onClick={toggleTheme}
                className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition"
                title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
              >
                {isDarkMode ? <Sun className="h-5 w-5" /> : <Moon className="h-5 w-5" />}
              </button>
              <div className="h-6 w-px bg-slate-200 dark:bg-slate-700 mx-1"></div>
              <button onClick={handleLogout} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition" title="Log Out">
                <LogOut className="h-5 w-5" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 w-full max-w-7xl mx-auto">
        {view === 'search' && (
          <SearchView 
            onSaveCollege={saveCollege} 
            savedCollegeNames={savedColleges.map(c => c.name)} 
          />
        )}
        {view === 'saved' && (
          <SavedCollegesView 
            colleges={savedColleges} 
            onRemove={removeCollege}
            onSetCareerCollege={navigateToCareer}
            darkMode={isDarkMode}
          />
        )}
        {view === 'career' && (
          <CareerPathView initialCollege={careerCollege} darkMode={isDarkMode} />
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface ChartProps {
  data: any[];
  dataKey: string;
  nameKey: string;
  color?: string;
  title: string;
  unit?: string;
  darkMode?: boolean;
  heightClass?: string;
}

const Chart: React.FC<ChartProps> = ({ 
  data, 
  dataKey, 
  nameKey, 
  color = "#4f46e5", 
  title, 
  unit = "", 
  darkMode = false,
  heightClass = "h-64 md:h-80"
}) => {
  const textColor = darkMode ? '#94a3b8' : '#64748b';
  const gridColor = darkMode ? '#334155' : '#e2e8f0';
  const tooltipBg = darkMode ? '#1e293b' : '#ffffff';
  const tooltipText = darkMode ? '#f8fafc' : '#0f172a';

  return (
    <div className={`w-full ${heightClass} bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 transition-colors`}>
      <h3 className="text-sm font-semibold text-slate-700 dark:text-slate-200 mb-4">{title}</h3>
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={data}
          margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
        >
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={gridColor} />
          <XAxis 
            dataKey={nameKey} 
            tick={{fontSize: 12, fill: textColor}} 
            axisLine={false}
            tickLine={false}
          />
          <YAxis 
            tick={{fontSize: 12, fill: textColor}} 
            axisLine={false}
            tickLine={false}
            tickFormatter={(value) => `${value}${unit}`}
          />
          <Tooltip 
            cursor={{fill: darkMode ? '#334155' : '#f1f5f9'}}
            contentStyle={{ 
              borderRadius: '8px', 
              border: 'none', 
              boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
              backgroundColor: tooltipBg,
              color: tooltipText
            }}
          />
          <Bar dataKey={dataKey} fill={color} radius={[4, 4, 0, 0]}>
            {data.map((entry, index) => (
               <Cell key={`cell-${index}`} fill={index % 2 === 0 ? color : `${color}cc`} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default Chart;

import React, { useState } from 'react';
import { findColleges, findCollegesFromTranscript } from '../services/gemini';
import { College, TranscriptAnalysisResult } from '../types';
import { Search, Upload, MapPin, Briefcase, Plus, Check, Loader2, FileText, DollarSign, BookOpen, Star, Sparkles, X } from 'lucide-react';

interface SearchViewProps {
  onSaveCollege: (college: College) => void;
  savedCollegeNames: string[];
}

const SearchView: React.FC<SearchViewProps> = ({ onSaveCollege, savedCollegeNames }) => {
  const [activeTab, setActiveTab] = useState<'manual' | 'transcript'>('manual');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<College[]>([]);

  // Manual Search State
  const [job, setJob] = useState('');
  const [location, setLocation] = useState('');

  // Transcript State
  const [transcriptAnalysis, setTranscriptAnalysis] = useState<TranscriptAnalysisResult | null>(null);
  const [fileName, setFileName] = useState('');

  const handleManualSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!job || !location) return;
    setLoading(true);
    setResults([]);
    setTranscriptAnalysis(null);
    try {
      const colleges = await findColleges(job, location);
      setResults(colleges);
    } catch (error) {
      console.error(error);
      alert("Failed to fetch colleges. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleTranscriptUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileName(file.name);
    setLoading(true);
    setResults([]);
    setTranscriptAnalysis(null);

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      const mimeType = file.type;

      try {
        const analysis = await findCollegesFromTranscript(base64Data, mimeType);
        if (analysis) {
          setTranscriptAnalysis(analysis);
          setResults(analysis.suggestedColleges);
        }
      } catch (error) {
        console.error(error);
        alert("Failed to analyze transcript.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const getFitIndicator = (reason: string) => {
    const r = reason.toLowerCase();
    if (r.includes('cost') || r.includes('afford') || r.includes('financial') || r.includes('tuition')) {
      return { 
        icon: DollarSign, 
        color: 'text-emerald-600 bg-emerald-50 border-emerald-100 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800', 
        label: 'Financial Fit' 
      };
    }
    if (r.includes('location') || r.includes('near') || r.includes('city') || r.includes('close')) {
      return { 
        icon: MapPin, 
        color: 'text-blue-600 bg-blue-50 border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800', 
        label: 'Location Fit' 
      };
    }
    if (r.includes('academic') || r.includes('program') || r.includes('major') || r.includes('rank')) {
      return { 
        icon: BookOpen, 
        color: 'text-purple-600 bg-purple-50 border-purple-100 dark:bg-purple-900/20 dark:text-purple-400 dark:border-purple-800', 
        label: 'Academic Fit' 
      };
    }
    if (r.includes('career') || r.includes('job') || r.includes('employ') || r.includes('industry')) {
      return { 
        icon: Briefcase, 
        color: 'text-amber-600 bg-amber-50 border-amber-100 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-800', 
        label: 'Career Fit' 
      };
    }
    if (r.includes('culture') || r.includes('life') || r.includes('social') || r.includes('vibe')) {
      return { 
        icon: Sparkles, 
        color: 'text-pink-600 bg-pink-50 border-pink-100 dark:bg-pink-900/20 dark:text-pink-400 dark:border-pink-800', 
        label: 'Cultural Fit' 
      };
    }
    return { 
      icon: Star, 
      color: 'text-indigo-600 bg-indigo-50 border-indigo-100 dark:bg-indigo-900/20 dark:text-indigo-400 dark:border-indigo-800', 
      label: 'Overall Fit' 
    };
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Tabs */}
      <div className="flex justify-center mb-8">
        <div className="bg-white dark:bg-slate-800 p-1 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex flex-col sm:flex-row w-full sm:w-auto transition-colors">
          <button
            onClick={() => setActiveTab('manual')}
            className={`px-6 py-2.5 rounded-lg text-sm font-medium transition-all text-center ${
              activeTab === 'manual' 
                ? 'bg-indigo-600 text-white shadow-md' 
                : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700'
            }`}
          >
            Manual Search
          </button>
          <button
            onClick={() => setActiveTab('transcript')}
            className={`px-6 py-2.5 rounded-lg text-sm font-medium transition-all text-center ${
              activeTab === 'transcript' 
                ? 'bg-indigo-600 text-white shadow-md' 
                : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700'
            }`}
          >
            Transcript Analysis
          </button>
        </div>
      </div>

      {/* Search Forms */}
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 p-6 mb-8 max-w-3xl mx-auto transition-colors">
        {activeTab === 'manual' ? (
          <form onSubmit={handleManualSearch} className="flex flex-col md:flex-row gap-4">
            <div className="flex-1 relative">
              <Briefcase className="absolute left-3 top-3.5 h-5 w-5 text-slate-400" />
              <input
                type="text"
                placeholder="Career Goal (e.g. Data Scientist)"
                className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={job}
                onChange={(e) => setJob(e.target.value)}
              />
            </div>
            <div className="flex-1 relative">
              <MapPin className="absolute left-3 top-3.5 h-5 w-5 text-slate-400" />
              <input
                type="text"
                placeholder="Location (e.g. CA)"
                className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={location}
                onChange={(e) => setLocation(e.target.value)}
              />
            </div>
            <button
              type="submit"
              disabled={loading}
              className="bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600 text-white px-8 py-3 rounded-lg font-medium transition flex items-center justify-center disabled:opacity-50"
            >
              {loading ? <Loader2 className="animate-spin h-5 w-5" /> : <Search className="h-5 w-5" />}
            </button>
          </form>
        ) : (
          <div className="text-center">
             <div className="border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-xl p-8 hover:bg-slate-50 dark:hover:bg-slate-700/50 transition cursor-pointer relative">
                <input 
                  type="file" 
                  accept="image/*" 
                  onChange={handleTranscriptUpload}
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                />
                <div className="flex flex-col items-center">
                  <div className="bg-indigo-50 dark:bg-indigo-900/30 p-3 rounded-full mb-3">
                    <Upload className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
                  </div>
                  <h3 className="text-sm font-semibold text-slate-900 dark:text-white">
                    {fileName ? fileName : 'Upload Transcript Image'}
                  </h3>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                    {fileName ? 'Click to change file' : 'PNG, JPG up to 5MB. AI will analyze your strengths.'}
                  </p>
                </div>
             </div>
             {loading && <div className="mt-4 flex justify-center text-sm text-indigo-600 dark:text-indigo-400 items-center gap-2"><Loader2 className="animate-spin h-4 w-4"/> Analyzing transcript...</div>}
          </div>
        )}
      </div>

      {/* Transcript Insights */}
      {transcriptAnalysis && (
        <div className="mb-8 p-6 bg-gradient-to-r from-indigo-50 to-purple-50 dark:from-indigo-900/20 dark:to-purple-900/20 rounded-2xl border border-indigo-100 dark:border-indigo-800">
          <h3 className="text-lg font-bold text-indigo-900 dark:text-indigo-300 mb-2 flex items-center gap-2">
            <FileText className="h-5 w-5"/> AI Insights
          </h3>
          <div className="grid md:grid-cols-2 gap-4 text-sm">
            <div>
              <span className="font-semibold text-indigo-700 dark:text-indigo-400">Inferred Goal:</span>
              <p className="text-slate-700 dark:text-slate-300">{transcriptAnalysis.inferredCareerGoal}</p>
            </div>
            <div>
              <span className="font-semibold text-indigo-700 dark:text-indigo-400">Suggested Degrees:</span>
              <div className="flex flex-wrap gap-2 mt-1">
                {transcriptAnalysis.suggestedDegrees.map((d, i) => (
                  <span key={i} className="bg-white dark:bg-slate-800 px-2 py-1 rounded text-indigo-600 dark:text-indigo-300 border border-indigo-100 dark:border-indigo-900 text-xs font-medium">{d}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Results Grid */}
      {results.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {results.map((college, idx) => {
            const isSaved = savedCollegeNames.includes(college.name);
            const fitIndicator = getFitIndicator(college.reasonForFit);
            const FitIcon = fitIndicator.icon;

            return (
              <div key={idx} className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 overflow-hidden hover:shadow-md transition-all flex flex-col group">
                <div className="p-5 flex-1 flex flex-col">
                  <div className="flex justify-between items-start mb-2">
                    <span className="inline-block px-2 py-1 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs font-medium">
                      {college.institutionType}
                    </span>
                    <span className="text-xs font-medium text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-2 py-1 rounded-full">
                       {(college.acceptanceRate * 100).toFixed(0)}% Acceptance
                    </span>
                  </div>
                  <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-1 group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors">{college.name}</h3>
                  <p className="text-sm text-slate-500 dark:text-slate-400 flex items-center gap-1 mb-3">
                    <MapPin className="h-3 w-3" /> {college.city}, {college.state}
                  </p>
                  <p className="text-sm text-slate-600 dark:text-slate-300 mb-4 line-clamp-3 flex-1">{college.description}</p>

                  {/* Visual Fit Indicator */}
                  <div className={`mt-auto rounded-lg border p-3 flex gap-3 ${fitIndicator.color}`}>
                    <div className="mt-0.5">
                      <FitIcon className="h-5 w-5" />
                    </div>
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-wider opacity-80 mb-0.5">{fitIndicator.label}</p>
                      <p className="text-sm font-medium leading-snug">{college.reasonForFit}</p>
                    </div>
                  </div>
                </div>

                <div className="p-4 border-t border-slate-100 dark:border-slate-700 flex items-center justify-between bg-slate-50 dark:bg-slate-800/50">
                  <div className="text-sm font-bold text-slate-900 dark:text-white">
                    ${college.annualCost.toLocaleString()}<span className="text-xs font-normal text-slate-500 dark:text-slate-400">/yr</span>
                  </div>
                  <button
                    onClick={() => !isSaved && onSaveCollege(college)}
                    disabled={isSaved}
                    className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium transition ${
                      isSaved 
                        ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 cursor-default' 
                        : 'bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600 text-white'
                    }`}
                  >
                    {isSaved ? <><Check className="h-3 w-3" /> Saved</> : <><Plus className="h-3 w-3" /> Save</>}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default SearchView;

import React, { useState, useEffect } from 'react';
import { College, CareerPath } from '../types';
import { getCareerPath } from '../services/gemini';
import { Loader2, ArrowRight, TrendingUp, Building2, Users } from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface CareerPathViewProps {
  initialCollege: College | null;
  darkMode?: boolean;
}

const CareerPathView: React.FC<CareerPathViewProps> = ({ initialCollege, darkMode = false }) => {
  const [college, setCollege] = useState<College | null>(initialCollege);
  const [careerGoal, setCareerGoal] = useState('');
  const [path, setPath] = useState<CareerPath | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    setCollege(initialCollege);
  }, [initialCollege]);

  const generatePath = async () => {
    if (!college || !careerGoal) return;
    setLoading(true);
    try {
      const data = await getCareerPath(college, careerGoal);
      setPath(data);
    } catch (e) {
      console.error(e);
      alert("Could not generate roadmap. Try again.");
    } finally {
      setLoading(false);
    }
  };

  if (!college) {
    return (
      <div className="text-center py-20 text-slate-500 dark:text-slate-400">
        Please select a college from your Saved list first.
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Input Section */}
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 p-8 mb-8 transition-colors">
        <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">Design Your Future at {college.name}</h2>
        <p className="text-slate-500 dark:text-slate-400 mb-6">Enter your dream job, and we'll create a step-by-step roadmap tailored to this institution.</p>

        <div className="flex flex-col sm:flex-row gap-4 max-w-xl">
          <input
            type="text"
            value={careerGoal}
            onChange={(e) => setCareerGoal(e.target.value)}
            placeholder="e.g. Software Engineer, Marine Biologist..."
            className="flex-1 px-4 py-3 rounded-lg border border-slate-200 dark:border-slate-600 dark:bg-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500 focus:outline-none"
          />
          <button
            onClick={generatePath}
            disabled={loading || !careerGoal}
            className="bg-indigo-600 hover:bg-indigo-700 dark:bg-indigo-500 dark:hover:bg-indigo-600 text-white px-6 py-3 rounded-lg font-medium transition flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {loading ? <Loader2 className="animate-spin h-5 w-5"/> : 'Generate Roadmap'}
          </button>
        </div>
      </div>

      {path && (
        <div className="space-y-8 animate-fade-in">
          {/* Header Stats */}
          <div className="grid md:grid-cols-3 gap-6">
            <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 transition-colors">
               <h3 className="text-sm font-semibold text-slate-500 dark:text-slate-400 mb-2">Salary Potential</h3>
               <div className="text-2xl font-bold text-green-600 dark:text-green-400">
                 ${path.salaryProjections.entryLevel.toLocaleString()} - ${path.salaryProjections.seniorLevel.toLocaleString()}
               </div>
               <p className="text-xs text-slate-400 mt-1">Entry to Senior Level</p>
            </div>
            <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 transition-colors">
               <h3 className="text-sm font-semibold text-slate-500 dark:text-slate-400 mb-2">Key Skills</h3>
               <div className="flex flex-wrap gap-2">
                 {path.keySkills.slice(0, 4).map((skill, i) => (
                   <span key={i} className="bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300 text-xs px-2 py-1 rounded font-medium">{skill}</span>
                 ))}
                 {path.keySkills.length > 4 && <span className="text-xs text-slate-400">+{path.keySkills.length - 4} more</span>}
               </div>
            </div>
            <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700 transition-colors">
               <h3 className="text-sm font-semibold text-slate-500 dark:text-slate-400 mb-2">Top Employers</h3>
               <div className="text-sm text-slate-700 dark:text-slate-300 space-y-1">
                 {path.hiringCompanies.slice(0, 3).map((co, i) => (
                   <div key={i} className="flex items-center gap-2"><Building2 className="h-3 w-3 text-slate-400"/> {co}</div>
                 ))}
               </div>
            </div>
          </div>

          <div className="grid lg:grid-cols-3 gap-8">
            {/* Timeline */}
